package com.appnexus.platform.persistence.organization;
import com.appnexus.platform.organization.OrganizationStructure;
import com.appnexus.platform.tenant.VerifiedTenantContext;
import java.nio.ByteBuffer; import java.sql.Timestamp; import java.time.Instant; import java.util.*;
import org.springframework.stereotype.Repository; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.context.request.*;
/** 组织领域持久化适配器；跨聚合写入在事务中校验，租户标识不接受客户端输入。 */
@Repository public class MyBatisOrganizationDomain implements OrganizationStructure {
 private final OrganizationDomainMapper mapper; public MyBatisOrganizationDomain(OrganizationDomainMapper mapper){this.mapper=mapper;}
 public List<Type> types(){return mapper.types(tenant()).stream().map(r->new Type(id(r,"id"),s(r,"code"),s(r,"name"),b(r,"enabled"),n(r,"version"))).toList();}
 public Type createType(String code,String name){var id=UUID.randomUUID();mapper.createType(tenant(),id.toString(),code,name);return new Type(id,code,name,true,0);}
 @Transactional public Type updateType(UUID id,String name,boolean enabled,long version){var current=types().stream().filter(v->v.id().equals(id)).findFirst().orElseThrow(this::missing);if(!enabled&&mapper.typeUsage(tenant(),id.toString())>0)throw new IllegalStateException("TYPE_IN_USE");if(mapper.updateType(tenant(),id.toString(),name,enabled,version)!=1)throw conflict();return new Type(id,current.code(),name,enabled,version+1);}
 public List<Unit> units(){return mapper.units(tenant()).stream().map(r->new Unit(id(r,"id"),s(r,"code"),id(r,"typeId"),nullableId(r,"parentId"),s(r,"name"),b(r,"enabled"),n(r,"version"))).toList();}
 @Transactional public Unit createUnit(String code,UUID typeId,UUID parentId,String name){validateParent(null,typeId,parentId);var id=UUID.randomUUID();mapper.createUnit(tenant(),id.toString(),code,typeId.toString(),text(parentId),name);return new Unit(id,code,typeId,parentId,name,true,0);}
 public Unit updateUnit(UUID id,String name,boolean enabled,long version){var current=unit(id);if(!enabled){var impact=impact(id);if(impact.children()>0||impact.relations()>0||impact.positions()>0||impact.activeAssignments()>0||impact.leaders()>0)throw new IllegalStateException("ORGANIZATION_IN_USE");}if(mapper.updateUnit(tenant(),id.toString(),name,enabled,version)!=1)throw conflict();return new Unit(id,current.code(),current.typeId(),current.parentId(),name,enabled,version+1);}
 @Transactional public Unit moveUnit(UUID id,UUID parentId,long version){mapper.lockUnits(tenant());var current=unit(id);validateParent(id,current.typeId(),parentId);for(UUID cursor=parentId;cursor!=null;){if(cursor.equals(id))throw new IllegalArgumentException("ORGANIZATION_CYCLE");cursor=unit(cursor).parentId();}if(mapper.moveUnit(tenant(),id.toString(),text(parentId),version)!=1)throw conflict();return new Unit(id,current.code(),current.typeId(),parentId,current.name(),current.enabled(),version+1);}
 public Impact impact(UUID id){unit(id);var r=mapper.impact(tenant(),id.toString());return new Impact(i(r,"children"),i(r,"relations"),i(r,"positions"),i(r,"activeAssignments"),i(r,"leaders"));}
 public List<Relation> relations(){return mapper.relations(tenant()).stream().map(r->new Relation(id(r,"id"),s(r,"relationType"),id(r,"sourceId"),id(r,"targetId"),n(r,"version"))).toList();}
 public Relation createRelation(String kind,UUID source,UUID target){if(source.equals(target))throw new IllegalArgumentException("SELF_RELATION");unit(source);unit(target);var id=UUID.randomUUID();mapper.createRelation(tenant(),id.toString(),kind,source.toString(),target.toString());return new Relation(id,kind,source,target,0);}
 public void deleteRelation(UUID id,long version){if(mapper.deleteRelation(tenant(),id.toString(),version)!=1)throw conflict();}
 public List<Position> positions(){return mapper.positions(tenant()).stream().map(r->new Position(id(r,"id"),id(r,"organizationId"),s(r,"code"),s(r,"name"),b(r,"enabled"),n(r,"version"))).toList();}
 public Position createPosition(UUID organizationId,String code,String name){if(!unit(organizationId).enabled())throw new IllegalArgumentException("ORGANIZATION_DISABLED");var id=UUID.randomUUID();mapper.createPosition(tenant(),id.toString(),organizationId.toString(),code,name);return new Position(id,organizationId,code,name,true,0);}
 @Transactional public Position updatePosition(UUID id,String name,boolean enabled,long version){var p=positions().stream().filter(v->v.id().equals(id)).findFirst().orElseThrow(this::missing);if(!enabled&&mapper.positionUsage(tenant(),id.toString())>0)throw new IllegalStateException("POSITION_IN_USE");if(mapper.updatePosition(tenant(),id.toString(),name,enabled,version)!=1)throw conflict();return new Position(id,p.organizationId(),p.code(),name,enabled,version+1);}
 public List<Assignment> assignments(){return mapper.assignments(tenant()).stream().map(r->new Assignment(id(r,"id"),id(r,"memberId"),id(r,"positionId"),instant(r,"startsAt"),nullableInstant(r,"endsAt"),b(r,"enabled"),n(r,"version"))).toList();}
 public Assignment createAssignment(UUID member,UUID position,Instant starts,Instant ends){if(ends!=null&&!ends.isAfter(starts))throw new IllegalArgumentException("INVALID_ASSIGNMENT_PERIOD");var id=UUID.randomUUID();if(mapper.createAssignment(tenant(),id.toString(),member.toString(),position.toString(),starts,ends)!=1)throw new IllegalArgumentException("MEMBER_OR_POSITION_UNAVAILABLE");return new Assignment(id,member,position,starts,ends,true,0);}
 @Transactional public Assignment updateAssignment(UUID id,Instant ends,boolean enabled,long version){var a=assignments().stream().filter(v->v.id().equals(id)).findFirst().orElseThrow(this::missing);if(ends!=null&&!ends.isAfter(a.startsAt()))throw new IllegalArgumentException("INVALID_ASSIGNMENT_PERIOD");if(mapper.updateAssignment(tenant(),id.toString(),ends,enabled,version)!=1)throw conflict();if(!enabled||(ends!=null&&!ends.isAfter(Instant.now())))mapper.removeAssignmentLeaders(tenant(),id.toString());return new Assignment(id,a.memberId(),a.positionId(),a.startsAt(),ends,enabled,version+1);}
 public List<Leader> leaders(){return mapper.leaders(tenant()).stream().map(r->new Leader(id(r,"organizationId"),id(r,"assignmentId"))).toList();}
 public void setLeader(UUID organization,UUID assignment,boolean selected){int changed=selected?mapper.addLeader(tenant(),organization.toString(),assignment.toString()):mapper.removeLeader(tenant(),organization.toString(),assignment.toString());if(changed!=1)throw new IllegalArgumentException("LEADER_ASSIGNMENT_UNAVAILABLE");}
 public List<Member> members(){return mapper.members(tenant()).stream().map(r->new Member(id(r,"id"),s(r,"displayName"))).toList();}
 private void validateParent(UUID self,UUID type,UUID parent){if(types().stream().noneMatch(v->v.id().equals(type)&&v.enabled()))throw new IllegalArgumentException("TYPE_UNAVAILABLE");if(parent!=null){var p=unit(parent);if(!p.typeId().equals(type)||!p.enabled()||parent.equals(self))throw new IllegalArgumentException("PARENT_UNAVAILABLE");}}
 private Unit unit(UUID id){return units().stream().filter(v->v.id().equals(id)).findFirst().orElseThrow(this::missing);} private IllegalStateException conflict(){return new IllegalStateException("CONCURRENT_MODIFICATION");} private NoSuchElementException missing(){return new NoSuchElementException("ORGANIZATION_OBJECT_NOT_FOUND");}
 private byte[] tenant(){var a=RequestContextHolder.getRequestAttributes();if(!(a instanceof ServletRequestAttributes s)||!(s.getRequest().getAttribute(VerifiedTenantContext.class.getName()) instanceof VerifiedTenantContext c))throw new IllegalStateException("Verified tenant context required");return ByteBuffer.allocate(16).putLong(c.tenantId().getMostSignificantBits()).putLong(c.tenantId().getLeastSignificantBits()).array();}
 private static String s(Map<String,Object> r,String k){return String.valueOf(r.get(k));} private static UUID id(Map<String,Object> r,String k){return UUID.fromString(s(r,k));} private static UUID nullableId(Map<String,Object> r,String k){return r.get(k)==null?null:id(r,k);} private static long n(Map<String,Object> r,String k){return ((Number)r.get(k)).longValue();} private static int i(Map<String,Object> r,String k){return ((Number)r.get(k)).intValue();} private static boolean b(Map<String,Object> r,String k){Object v=r.get(k);return Boolean.TRUE.equals(v)||(v instanceof Number x&&x.intValue()!=0);} private static String text(UUID id){return id==null?null:id.toString();} private static Instant instant(Map<String,Object> r,String k){Object v=r.get(k);return v instanceof Timestamp t?t.toInstant():(Instant)v;} private static Instant nullableInstant(Map<String,Object> r,String k){return r.get(k)==null?null:instant(r,k);}
}
